package com.tekwatt.admin.config;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.web.client.RestClient;@Configuration public class ServiceClients{@Bean("tenantClient")RestClient tenant(RestClient.Builder b,@Value("${tekwatt.services.tenant}")String url){return b.clone().baseUrl(url).build();}@Bean("userClient")RestClient user(RestClient.Builder b,@Value("${tekwatt.services.user}")String url){return b.clone().baseUrl(url).build();}@Bean("chargerClient")RestClient charger(RestClient.Builder b,@Value("${tekwatt.services.charger}")String url){return b.clone().baseUrl(url).build();}@Bean("ocppClient")RestClient ocpp(RestClient.Builder b,@Value("${tekwatt.services.ocpp}")String url){return b.clone().baseUrl(url).build();}}
